        let basis = sh_basis(&dir);

        // For (x, y, z) = (1/sqrt(3), 1/sqrt(3), 1/sqrt(3)):
        let x = 1.0 / 3.0f32.sqrt();
        let y = 1.0 / 3.0f32.sqrt();
        let z = 1.0 / 3.0f32.sqrt();

        // Constants from src/core/sh.rs
