        assert!((basis[7] - ref_basis_2_1).abs() < TOLERANCE,
            "Y_2^1 mismatch: {} vs {}", basis[7], ref_basis_2_1);
        assert!((basis[8] - ref_basis_2_2).abs() < TOLERANCE,
