        let expected = Matrix3::identity();

        println!("  Rotation: 90° around Z-axis");
        println!("  Expected covariance:\n{}", expected);
        println!("  Computed covariance:\n{}", covariance);

        // Verify elements match
        for i in 0..3 {
            for j in 0..3 {
