        // Scale in log-space: log([2, 3, 4])
        let sx = 2.0f32;
        let sy = 3.0f32;
        let sz = 4.0f32;
        let log_scale = Vector3::new(sx.ln(), sy.ln(), sz.ln());
        let rotation = UnitQuaternion::identity();

        let gaussian = Gaussian::new(
            Vector3::zeros(),
            log_scale,
