        println!("Test 3 - 90° Z-rotation, uniform scale:");

        // Scale: [1, 1, 1]
        let log_scale = Vector3::new(0.0, 0.0, 0.0);

        // 90° rotation around Z-axis
        let angle = std::f32::consts::FRAC_PI_2;
